import{_ as i,l as c,o as a,c as l,v as o,p as r,x as d,d as n,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"ICF 同码折叠","description":"","frontmatter":{"title":"ICF 同码折叠","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/icf-identical-code-folding.md","filePath":"cs/icf-identical-code-folding.md","lastUpdated":1789023840000}'),h={name:"cs/icf-identical-code-folding.md"};function C(f,e,E,_,m,F){const t=c("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="icf-同码折叠" tabindex="-1">ICF 同码折叠 <a class="header-anchor" href="#icf-同码折叠" aria-label="Permalink to &quot;ICF 同码折叠&quot;">​</a></h1><div class="epigraph"><p>若两个函数的机器码与可重定位引用等价，链接器可只留一份，其余改成别名。这是空间优化，不是源级 CSE。</p><footer>—— 据 Gold/lld 的 ICF（Identical Code Folding）；Microsoft `/OPT:ICF`；对照[CSE](/cs/cse-gvn) 整理</footer></div><p>上一课<a href="/cs/relocation-types">重定位类型</a> 决定字节如何填。缺口是<strong>多份相同已生成代码</strong>：模板、单态化、空函数。ICF：比较节内容（含重定位模式），合并。本课钉何时合法（函数指针身份），ELF 格式下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>C++ 模板对每个 <code>T</code> 生成 <code>swap</code>，体可能相同。ICF 合并。若程序用函数指针比身份，合并会改变 <code>f==g</code>。故：只对 <code>unnamed_addr</code> 或语言允许的符号做，或保守不做可观测身份。缺口是<strong>等价 + 身份</strong>，不是 GVN 哈希。</p><p>Safe ICF vs 全 ICF：安全模式避免合并地址被取的函数。</p><h3 id="icf-不是-comdat-弱符号" tabindex="-1">ICF 不是 COMDAT 弱符号 <a class="header-anchor" href="#icf-不是-comdat-弱符号" aria-label="Permalink to &quot;ICF 不是 COMDAT 弱符号&quot;">​</a></h3><p>COMDAT 解决「同一模板在多 TU 定义，留一份」。ICF 解决「不同符号碰巧同码」。二者可叠。</p><p><span class="marginnote">MSVC ICF。gold <code>--icf</code>。lld。LLVM <code>unnamed_addr</code>。本课链接期；编译器也可 merge functions 遍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按节哈希分桶，逐字节+重定位比较。合并后：符号指向同一地址，丢重复节。与 <code>--gc-sections</code> 顺序：先垃圾回收再 ICF 或反之，实现相关。</p>',11)),(a(),r(p,null,{default:d(()=>[s(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEC%5B%22%E5%87%BD%E6%95%B0%E8%8A%82%22%5D%20--%3E%20EQ%5B%22%E7%A0%81%E4%B8%8E%E9%87%8D%E5%AE%9A%E4%BD%8D%E7%AD%89%E4%BB%B7%22%5D%0A%20%20EQ%20--%3E%20FOLD%5B%22%E7%95%99%E4%B8%80%E4%BB%BD%22%5D%0A%20%20FOLD%20--%3E%20ALIAS%5B%22%E5%85%B6%E4%BD%99%E5%88%AB%E5%90%8D%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与单态化：膨胀后再 ICF 收回一部分，但不能当不膨胀的理由。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>调试：多源函数同一地址，DWARF 要能表示。 unwinding：同一 FDE。不要合并后忽略不同的 <code>.eh_frame</code> 个性。</p><p>相对：字符串折叠（merge rodata）是数据侧同类。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 ELF 头。后课默认：同码可折叠，身份需许可。下一课 ELF 格式：节、段、符号表放哪。</p><p>也不把 ICF 当压缩算法课（gzip）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ICF：链接期合并等价机器码。</li><li>函数指针身份是合法性边界。</li><li>与 COMDAT、gc-sections、单态化 complementary。</li><li>出处：gold/lld ICF；MSVC <code>/OPT:ICF</code>；对照 CSE。</li></ul>',9))])}const g=i(h,[["render",C]]);export{I as __pageData,g as default};
